appendedCSS:
/* Fresh review: preserve one complete local chat message in short landscape. */
@media(max-height:500px) and (min-width:701px){
 .chat-panel ol{min-height:80px;margin:2px 0 6px}
 .chat-panel form{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 8px}
 .chat-panel label{grid-column:1/-1;font-size:11px;line-height:13px;margin:0}
 .chat-panel form button{margin:0;font-size:12px;min-height:44px;padding:8px 12px}
 .chat-panel input{height:44px;min-width:0}
 .chat-panel>p{font-size:10px;line-height:13px;margin:4px 0 0}
}
